insert into public.site_settings(key,value,is_public)
values
  ('saved_copy_ar', to_jsonb(E'eyebrow || قائمتك\ntitle || الوظائف المحفوظة\nleadSaved || {count} وظيفة محفوظة في هذا المتصفح. راجع الأهلية قبل أن تتقدم.\nleadEmpty || احفظ أي وظيفة للعودة إليها لاحقاً ومقارنتها بغيرها.\nclearAll || مسح الكل\nemptyTitle || لا توجد وظائف محفوظة بعد\nemptyBody || اضغط «احفظ» في أي بطاقة وظيفة، وستجدها هنا.\nbrowseJobs || تصفّح الوظائف\nremove || إزالة من المحفوظات\nmetaTitle || الوظائف المحفوظة | ezyjobs\nmetaDescription || قائمة الوظائف التي حفظتها لمقارنتها لاحقاً.'::text), true),
  ('saved_copy_en', to_jsonb(E'eyebrow || Saved jobs\ntitle || Saved jobs\nleadSaved || {count} jobs saved in this browser. Check eligibility before you apply.\nleadEmpty || Save a job to come back to it later and compare it with other opportunities.\nclearAll || Clear all\nemptyTitle || No saved jobs yet\nemptyBody || Select Save on any job card and it will appear here.\nbrowseJobs || Browse jobs\nremove || Remove from saved jobs\nmetaTitle || Saved jobs | ezyjobs\nmetaDescription || Jobs you saved to compare later.'::text), true),
  ('saved_copy_fr', to_jsonb(E'eyebrow || Vos offres\ntitle || Offres enregistrées\nleadSaved || {count} offres enregistrées dans ce navigateur. Vérifiez l’éligibilité avant de postuler.\nleadEmpty || Enregistrez une offre pour la retrouver plus tard et la comparer à d’autres opportunités.\nclearAll || Tout effacer\nemptyTitle || Aucune offre enregistrée\nemptyBody || Cliquez sur « Enregistrer » sur une offre pour la retrouver ici.\nbrowseJobs || Voir les offres\nremove || Retirer des favoris\nmetaTitle || Offres enregistrées | ezyjobs\nmetaDescription || Les offres que vous avez enregistrées pour les comparer plus tard.'::text), true),
  ('application_kit_copy_ar', to_jsonb(E'eyebrow || Application Kit\nlead || تجهيز موجّه لهذه الوظيفة قبل الانتقال إلى جهة التوظيف الرسمية. الحالة الحالية: {status}.\nopenApplication || افتح صفحة التقديم\nhighlightsTitle || ما الذي تبرزه من ملفك؟\nhighlightsLead || هذه المهارات ظهرت في ملفك وتتقاطع مع إعلان الوظيفة.\nnoHighlights || لا يوجد تطابق واضح في المهارات المحفوظة.\ngapsTitle || فجوات تحتاج انتباهاً\ngapsLead || ليست حكماً بالرفض؛ فقط عناصر قد تحتاج توضيحاً أو تحضيراً.\nnoGaps || لم نجد فجوات مهارية واضحة.\ncoverTitle || Cover Letter — مسودة قابلة للتعديل\ncoverLead || راجعها وعدّلها قبل الإرسال؛ هذه مسودة مساعدة وليست رسالة نهائية تلقائياً.\nfitTitle || إجابة: Why are you a good fit?\nchecklistTitle || Checklist قبل التقديم\ncheckCv || راجع CV وتأكد أن المهارات الأكثر صلة ظاهرة.\ncheckEligibility || راجع شرط الدولة والأهلية الجغرافية.\ncheckCover || عدّل Cover Letter حسب الشركة والوظيفة.\ncheckOfficial || قدّم من رابط المصدر الرسمي.\napplyNow || التقديم الآن\nbackApplications || العودة إلى تقديماتي\nnotFoundTitle || لم نجد الوظيفة\nnotFoundBody || قد يكون الرابط قديماً أو أزيلت الوظيفة من البيانات.\nmetaTitle || Application Kit | ezyjobs\nmetaDescription || جهّز عناصر التقديم قبل فتح المصدر الرسمي.'::text), true),
  ('application_kit_copy_en', to_jsonb(E'eyebrow || Application Kit\nlead || Prepare this role before moving to the official employer source. Current status: {status}.\nopenApplication || Open application page\nhighlightsTitle || What should you highlight?\nhighlightsLead || These skills appear in your profile and overlap with the job posting.\nnoHighlights || No clear overlap in your saved skills.\ngapsTitle || Gaps to review\ngapsLead || Not a rejection decision; these are items you may need to clarify or prepare for.\nnoGaps || No clear skill gaps found.\ncoverTitle || Cover Letter — editable draft\ncoverLead || Review and edit it before sending; this is an assisted draft, not an automatically final message.\nfitTitle || Answer: Why are you a good fit?\nchecklistTitle || Pre-application checklist\ncheckCv || Review your CV and make sure the most relevant skills are visible.\ncheckEligibility || Review country and geographic eligibility.\ncheckCover || Tailor the cover letter to the company and role.\ncheckOfficial || Apply through the official source link.\napplyNow || Apply now\nbackApplications || Back to applications\nnotFoundTitle || We could not find the job\nnotFoundBody || The link may be outdated or the job may have been removed.\nmetaTitle || Application Kit | ezyjobs\nmetaDescription || Prepare application materials before opening the official source.'::text), true),
  ('application_kit_copy_fr', to_jsonb(E'eyebrow || Dossier de candidature\nlead || Préparez cette offre avant d’ouvrir la source officielle. Statut actuel : {status}.\nopenApplication || Ouvrir la page de candidature\nhighlightsTitle || Que mettre en avant ?\nhighlightsLead || Ces compétences figurent dans votre profil et correspondent à l’offre.\nnoHighlights || Aucun recoupement clair dans vos compétences enregistrées.\ngapsTitle || Points à revoir\ngapsLead || Ce n’est pas un verdict de refus ; ce sont des éléments à clarifier ou à préparer.\nnoGaps || Aucune lacune claire détectée.\ncoverTitle || Lettre de motivation — brouillon modifiable\ncoverLead || Relisez-la et modifiez-la avant l’envoi ; il s’agit d’un brouillon d’aide.\nfitTitle || Réponse : Why are you a good fit ?\nchecklistTitle || Checklist avant candidature\ncheckCv || Vérifiez votre CV et rendez visibles les compétences les plus pertinentes.\ncheckEligibility || Vérifiez le pays et l’éligibilité géographique.\ncheckCover || Adaptez la lettre à l’entreprise et au poste.\ncheckOfficial || Postulez via le lien de la source officielle.\napplyNow || Postuler maintenant\nbackApplications || Retour à mes candidatures\nnotFoundTitle || Offre introuvable\nnotFoundBody || Le lien est peut-être obsolète ou l’offre a été supprimée.\nmetaTitle || Dossier de candidature | ezyjobs\nmetaDescription || Préparez vos éléments de candidature avant d’ouvrir la source officielle.'::text), true)
